<?php
/**
 * index.php — the home page is the blog.
 *
 * The listing itself is generated by tools/build.php into blog/_home.php, the
 * same directory .gitignore already treats as build output, so this file stays
 * a tracked one-liner that never churns on a rebuild. /blog/ is a 301 back to
 * here; individual essays keep living at /blog/<slug>/.
 */

declare(strict_types=1);

$home = __DIR__ . '/blog/_home.php';
if (is_file($home)) {
    require $home;
    return;
}

require_once __DIR__ . '/lib/config.php';
require_once __DIR__ . '/lib/helpers.php';
require_once __DIR__ . '/lib/page.php';

http_response_code(503);
echo page_head('Field Notes', 'Not built yet.', cfg('site_url') . '/', '<meta name="robots" content="noindex">');
echo site_nav('blog');
echo '<main class="wrap"><div class="section-head blog-hero"><h1>Not built yet</h1>'
   . '<p>Fresh clone — run <code>php tools/build.php</code> to generate the blog.</p></div></main>';
echo site_footer();
